symbol from "/ws/EvtWorks/cod-project/tests/cod/language/symbolic-vocabulary.cod" @right;
effect @arena <- make ContextPool(capacity = 4096u64) { tag <- 1 };
effect @left = deref(alloc @arena ContextNode(10)), @right = deref(alloc @arena ContextNode(20));
effect proc @read() -> i64 { if (false) { touch @right } else {}; @left.value };
{
  effect @arena <- make ContextPool(capacity = 4096u64) { tag <- 2 };
  effect @left = deref(alloc @arena ContextNode(30)), @right = deref(alloc @arena ContextNode(40));
  perform @read()
};

data Node { value::i64; } data Holder { prefix::i64; item::ref<Node>; }
function read_only(x::ref<Node>) -> const ref<Node> { x }
region symbol @arena::Holder;
effect @arena <- make Holder(capacity=4096u64) { prefix <- 0; item <- null };
{ let node=alloc @arena Node(1); setfield(root(@arena),item,read_only(node)); };
